// Package invui draws menus in a chest window kept open while the server
// rewrites its slots: every element of a screen is a slot whose item and
// name the inventoryui pack's sg_menu.json draws (generated by
// common/tools/invuigen from this layout), and a press on a slot drops one
// item, which the server cancels and answers.
package invui

// Marker in the window title makes the pack draw the menu window.
const Marker = "§s§g§m§u"

// Size is the number of slots of the menu window.
const Size = 243

// The slots every screen shares.
const (
	SlotKey   = 0
	SlotTitle = 1
	SlotBody  = 2
)

// Tabs are the tabs over the window: an icon and a button slot each.
const (
	Tabs     = 8
	TabIcon0 = 3
	TabBtn0  = TabIcon0 + Tabs
)

// Bars are the buttons of the control bar, left of the close button.
const (
	Bars     = 6
	BarIcon0 = TabBtn0 + Tabs
	BarBtn0  = BarIcon0 + Bars
)

// Rows are the rows of the list under the body text.
const (
	Rows     = 48
	RowIcon0 = BarBtn0 + Bars
	RowBtn0  = RowIcon0 + Rows
)

// Kind markers end a button slot's name and say what the slot draws. They
// are invisible format codes the pack takes off the text.
const (
	KindRow       = "§z§a"
	KindStatic    = "§z§s"
	KindHeading   = "§z§h"
	KindDivider   = "§z§d"
	KindToggleOff = "§z§o"
	KindToggleOn  = "§z§x"
	KindTab       = "§z§t"
	KindTabOn     = "§z§u"
	KindBar       = "§z§b"
	KindHelp      = "§z§q"
	KindIcon      = "§z§i"
)

// Kinds are the kind markers in the order the pack strips them.
var Kinds = []string{KindRow, KindStatic, KindHeading, KindDivider, KindToggleOff, KindToggleOn, KindTab, KindTabOn, KindBar, KindHelp, KindIcon}
